    assert(max == 5 && min == 3);

    find_max_min(10, -2, 7, &max, &min);
    assert(max == 10 && min == -2);

    find_max_min(-1, -3, -2, &max, &min);
    assert(max == -1 && min == -3);

    return 0;
}

