#include <cassert>
#include <iostream>
int count_coloring_methods(int n, int m)
{
    int f[1111]; // Array to store results
    if (n == 1) return m;
    if (n == 2) return static_cast<long long>(m) * (m - 1) % 1000003;
    // Initialize the first three elements
    f[1] = m;
    f[2] = static_cast<long long>(m) * (m - 1) % 1000003;
    // Formula derived from the given gold.c code
    f[3] = static_cast<long long>(f[2]) * (m - 2) % 1000003;
    for(int i = 4; i <= n; ++i) {
        f[i] = (static_cast<long long>(f[i - 1]) * (m - 2) % 1000003 +
                static_cast<long long>(f[i - 2]) * (m - 1) % 1000003) % 1000003;
    }
    return f[n];
}

