/**
 * Given two positive integers n and k, find the number of positive integers x,
 * where 1 <= x <= n, that can be expressed as x = a^b with a and b being
 * positive integers and b >= k. Different legal representations of x are counted
 * only once. For example:
 *     >>> countPowerNumbers(99, 1)
 *     99
 */
int countPowerNumbers(int n, int k)

source_record.canonical_solution:
{
    int count = 0;
    int x = 0;
    bool *mp = (bool *)calloc(n + 1, sizeof(bool));

    for (int i = 2; i <= cbrt(n); ++i) {
        long long t = i * i;
        int m = 2;
        while (t <= n / i) {
            t *= i;
            m++;
            if (m < k || mp[t]) continue;
            if ((int)sqrt(t) * (int)sqrt(t) == t) x++;
            mp[t] = true;
            count++;
        }
    }
    if (k == 1) {
        count = n;
    } else if (k >= 3) {
        count += 1;
    } else {
        count += static_cast<int>(sqrt(n)) - x;
    }
    free(mp);
    return count;
}

