 * >>> countTriplets({1, 5, 7})
 * 1
 */
int countTriplets(const std::vector<int>& heights)

source_record.canonical_solution:
{
    int count = 0;
    int n = heights.size();
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            for (int k = j + 1; k < n; ++k) {
                int minVal = std::min({heights[i], heights[j], heights[k]});
                int maxVal = std::max({heights[i], heights[j], heights[k]});

                // GCD algorithm
                int a = minVal, b = maxVal;
                while (b != 0) {
                    int t = b;
                    b = a % b;
                    a = t;
                }

                if (a == 1) {
                    count++;
                }
            }
        }
    }
    return count;
}

